mapper.insert:
INSERT INTO file_job (
    id, job_type, data_type_code, file_format, status,
    filter_snapshot, requested_by
) VALUES (
    #{id,jdbcType=OTHER}, 'EXPORT', #{dataTypeCode}, 'CSV', 'PENDING',
    CAST(#{filterSnapshot} AS jsonb), #{requestedBy,jdbcType=OTHER}
)

mapper.update:
UPDATE file_job
SET status = 'RUNNING', started_at = now(), updated_at = now()
WHERE id = #{id,jdbcType=OTHER}
  AND job_type = 'EXPORT'
  AND requested_by = #{requestedBy,jdbcType=OTHER}
  AND status = 'PENDING'

UPDATE file_job
SET status = 'FAILED', error_message = #{errorMessage}, completed_at = now(), updated_at = now()
WHERE id = #{id,jdbcType=OTHER}
  AND job_type = 'EXPORT'
  AND requested_by = #{requestedBy,jdbcType=OTHER}

mapper.delete:
DELETE FROM file_job
WHERE id = #{id,jdbcType=OTHER}
  AND job_type = 'EXPORT'
  AND requested_by = #{requestedBy,jdbcType=OTHER}

mapper.select:
SELECT id, status, data_type_code, result_file_name AS file_name, storage_path,
       file_format AS format, total_rows, success_rows, failed_rows, error_message,
       created_at, completed_at
FROM file_job
WHERE job_type = 'EXPORT'
  AND requested_by = #{requestedBy,jdbcType=OTHER}
ORDER BY created_at DESC, id DESC
LIMIT #{pageSize}
OFFSET #{offset}
